{
  "name": "todomvc-shakedown",
  "version": "0.1.0",
  "private": true,
  "scripts": { "test": "cucumber-js" },
  "devDependencies": { "@cucumber/cucumber": "*", "happy-dom": "*" }
}

/**
 * @fileoverview TodoMVC implementation — vanilla JS.
 * @planks("I open the todo app")
 * @planks("there are no todos")
 * @planks("the main section should not be visible")
 * @planks("the footer should not be visible")
 * @planks("I type {string} in the new-todo input and press Enter")
 * @planks("the todo list shows {int} item")
 * @planks("the new item is {string}")
 * @planks("the new-todo input is cleared")
 * @planks("the todo list shows {int} items")
 * @planks("I have a todo {string}")
 * @planks("I have a completed todo {string}")
 * @planks("I have todos {string} and {string}")
 * @planks("I click the toggle checkbox for {string}")
 * @planks("the todo {string} should be marked completed")
 * @planks("the todo {string} should be marked active")
 * @planks("I click the toggle-all checkbox")
 * @planks("all todos are marked completed")
 * @planks("I click {string}")
 * @planks("the toggle-all checkbox should not be checked")
 * @planks("the toggle-all checkbox should be unchecked")
 * @planks("the toggle-all checkbox should be checked")
 * @planks("I mark {string} as completed")
 * @planks("I also mark {string} as completed")
 * @planks("I double-click the label for {string}")
 * @planks("the editing input should be visible for {string}")
 * @planks("I edit {string} to {string} and press Enter")
 * @planks("I edit {string} to {string} and blur the input")
 * @planks("I edit {string} to {string} and press Escape")
 * @planks("the todo list shows {string}")
 * @planks("the todo {string} should not exist")
 * @planks("the edit is cancelled")
 * @planks("I click the destroy button for {string}")
 * @planks("the todo-count shows {string}")
 * @planks("{string} is completed")
 * @planks("{string} should not exist")
 * @planks("the clear-completed button should not be visible")
 * @planks("the clear-completed button should be visible")
 * @planks("I reload the todo app")
 * @planks("I follow the {string} filter link")
 * @planks("I see {int} todos in the list")
 * @planks("I see {int} todo in the list")
 * @planks("that todo is {string}")
 * @planks("the {string} filter link has class {string}")
 * @planks("the {string} filter link does not have class {string}")
 * @planks("I am on the todo app")
 * @planks("the {string} filter is selected")
 * @planks("the todo is saved in localStorage with key {string}")
 * @planks("localStorage has a todo {string}")
 * @planks("{string} should not be visible in the list")
 * @planks("I start editing {string}")
 * @planks("the todo {string} should not be in editing mode")
 * @planks("Active filter persists on reload")
 * @planks("Editing mode is not persisted")
 */
(() => {
	const ENTER_KEY = 13;
	const ESCAPE_KEY = 27;
	var STORAGE_KEY = "todos-vanillajs";

	// ── Model ──────────────────────────────────────────────────────────────────

	let todos = loadTodos();

	function loadTodos() {
		try {
			return JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
		} catch (_) {
			return [];
		}
	}

	function saveTodos() {
		localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
	}

	// ── Selectors ───────────────────────────────────────────────────────────────

	const mainEl = document.querySelector(".main");
	const footerEl = document.querySelector(".footer");
	const todoList = document.querySelector(".todo-list");
	const newTodoInput = document.querySelector(".new-todo");
	const toggleAll = document.querySelector(".toggle-all");
	const todoCountEl = document.querySelector(".todo-count");
	const clearCompletedBtn = document.querySelector(".clear-completed");
	const filterLinks = document.querySelectorAll(".filters a");

	// ── Router ──────────────────────────────────────────────────────────────────

	var currentFilter = "all";

	function getFilterFromHash() {
		const hash = window.location.hash || "#/";
		if (hash === "#/" || hash === "" || hash === "#") return "all";
		if (hash === "#/active") return "active";
		if (hash === "#/completed") return "completed";
		return "all";
	}

	function updateFilterLinks() {
		for (let i = 0; i < filterLinks.length; i++) {
			const link = filterLinks[i];
			const href = link.getAttribute("href");
			let isSelected = false;
			if (currentFilter === "all" && (href === "#/" || href === "#"))
				isSelected = true;
			else if (currentFilter === "active" && href === "#/active")
				isSelected = true;
			else if (currentFilter === "completed" && href === "#/completed")
				isSelected = true;
			if (isSelected) {
				link.classList.add("selected");
			} else {
				link.classList.remove("selected");
			}
		}
	}

	function getFilteredTodos() {
		if (currentFilter === "active") return todos.filter((t) => !t.completed);
		if (currentFilter === "completed") return todos.filter((t) => t.completed);
		return todos;
	}

	function onHashChange() {
		currentFilter = getFilterFromHash();
		updateFilterLinks();
		render();
	}

	window.addEventListener("hashchange", onHashChange);
	// Initialise filter on load
	currentFilter = getFilterFromHash();

	// ── Render ──────────────────────────────────────────────────────────────────

	function render() {
		const filtered = getFilteredTodos();
		const completedCount = todos.filter((t) => t.completed).length;
		const activeCount = todos.length - completedCount;

		// Show/hide main and footer
		const hasTodos = todos.length > 0;
		mainEl.style.display = hasTodos ? "block" : "none";
		footerEl.style.display = hasTodos ? "block" : "none";

		// Toggle-all state
		toggleAll.checked = todos.length > 0 && completedCount === todos.length;

		// Render todo items
		renderList(filtered);

		// Update counter
		updateCounter(activeCount);

		// Clear completed visibility
		clearCompletedBtn.style.display = completedCount > 0 ? "block" : "none";
	}

	function renderList(filtered) {
		todoList.innerHTML = "";
		for (let i = 0; i < filtered.length; i++) {
			const todo = filtered[i];
			const li = document.createElement("li");
			if (todo.completed) li.classList.add("completed");

			const viewDiv = document.createElement("div");
			viewDiv.classList.add("view");

			const toggleCheckbox = document.createElement("input");
			toggleCheckbox.classList.add("toggle");
			toggleCheckbox.type = "checkbox";
			toggleCheckbox.checked = todo.completed;

			((todoRef) => {
				toggleCheckbox.addEventListener("change", () => {
					todoRef.completed = !todoRef.completed;
					saveTodos();
					render();
				});
			})(todo);

			const label = document.createElement("label");
			label.textContent = todo.title;

			((todoRef) => {
				label.addEventListener("dblclick", function () {
					// Enter editing mode
					var item = this.closest("li");
					item.classList.add("editing");
					var editInput = item.querySelector(".edit");
					editInput.value = todoRef.title;
					editInput.focus();

					const finishEdit = (save) => {
						const val = editInput.value.trim();
						if (save && val) {
							todoRef.title = val;
							saveTodos();
						} else if (save && !val) {
							// Empty — destroy
							const idx = todos.indexOf(todoRef);
							if (idx !== -1) todos.splice(idx, 1);
							saveTodos();
						}
						item.classList.remove("editing");
						render();
					};

					function onKeydown(e) {
						if (e.keyCode === ENTER_KEY) {
							e.preventDefault();
							editInput.removeEventListener("keydown", onKeydown);
							editInput.removeEventListener("blur", onBlur);
							finishEdit(true);
						} else if (e.keyCode === ESCAPE_KEY) {
							e.preventDefault();
							editInput.removeEventListener("keydown", onKeydown);
							editInput.removeEventListener("blur", onBlur);
							// Cancel — restore original title
							item.classList.remove("editing");
						}
					}

					function onBlur() {
						editInput.removeEventListener("keydown", onKeydown);
						editInput.removeEventListener("blur", onBlur);
						finishEdit(true);
					}

					editInput.addEventListener("keydown", onKeydown);
					setTimeout(() => {
						editInput.addEventListener("blur", onBlur);
					}, 0);
				});
			})(todo);

			const destroyBtn = document.createElement("button");
			destroyBtn.classList.add("destroy");

			((todoRef) => {
				destroyBtn.addEventListener("click", () => {
					var idx = todos.indexOf(todoRef);
					if (idx !== -1) todos.splice(idx, 1);
					saveTodos();
					render();
				});
			})(todo);

			viewDiv.appendChild(toggleCheckbox);
			viewDiv.appendChild(label);
			viewDiv.appendChild(destroyBtn);
			li.appendChild(viewDiv);

			const editInput = document.createElement("input");
			editInput.classList.add("edit");
			editInput.value = todo.title;
			li.appendChild(editInput);

			// Hide items that don't match current filter via display
			const inFilter =
				currentFilter === "all" ||
				(currentFilter === "active" && !todo.completed) ||
				(currentFilter === "completed" && todo.completed);
			if (!inFilter) li.style.display = "none";

			todoList.appendChild(li);
		}
	}

	function updateCounter(activeCount) {
		const word = activeCount === 1 ? "item" : "items";
		todoCountEl.innerHTML = `<strong>${activeCount}</strong> ${word} left`;
	}

	// ── Actions ─────────────────────────────────────────────────────────────────

	newTodoInput.addEventListener("keydown", (e) => {
		if (e.keyCode === ENTER_KEY) {
			e.preventDefault();
			const title = newTodoInput.value.trim();
			if (title) {
				todos.push({ id: Date.now(), title: title, completed: false });
				saveTodos();
				newTodoInput.value = "";
				render();
			}
		}
	});

	toggleAll.addEventListener("change", () => {
		const allCompleted = todos.length > 0 && todos.every((t) => t.completed);
		for (let i = 0; i < todos.length; i++) {
			todos[i].completed = !allCompleted;
		}
		saveTodos();
		render();
	});

	clearCompletedBtn.addEventListener("click", () => {
		todos = todos.filter((t) => !t.completed);
		saveTodos();
		render();
	});

	// ── Initial render ──────────────────────────────────────────────────────────

	render();
})();

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp() {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // Reload the app while preserving localStorage and hash state.
  reload() {
    // Snapshot current state
    const ls = this.window.localStorage;
    const saved = {};
    for (let i = 0; i < ls.length; i++) {
      const k = ls.key(i);
      saved[k] = ls.getItem(k);
    }
    const hash = this.window.location.hash;

    this.disposeApp();

    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error('verification support: ' + indexPath + ' does not exist');
    if (!fs.existsSync(appPath))
      throw new Error('verification support: ' + appPath + ' does not exist');
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error('verification support: ' + appPath + ' is empty');

    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // Restore localStorage BEFORE app code runs
    const newLs = this.window.localStorage;
    for (const k of Object.keys(saved)) {
      newLs.setItem(k, saved[k]);
    }

    // Load the page and execute the app with preserved state
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // Re-attach routing click intercept
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);

    // Restore hash after app init
    if (hash && hash !== '#/') {
      this.window.location.hash = hash;
      this.window.dispatchEvent(new this.window.Event('hashchange'));
    }
  }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () { this.loadApp(); });
// ...and every scenario gives it back.
After(async function () { await this.disposeApp(); });

const { Given, When, Then } = require('@cucumber/cucumber');
const { assert } = require('console');

// ── Helpers ──────────────────────────────────────────────────────────────────

function query(selector) {
  const el = this.document.querySelector(selector);
  if (!el) throw new Error(`query: selector "${selector}" matched nothing`);
  return el;
}

function isVisible(el) {
  if (!el) return false;
  // happy-dom does not render computed styles; check the hidden attribute and the
  // section's "display:none" / "visibility:hidden" inline style. The TodoMVC template
  // hides #main and #footer when there are no todos via a class or inline style.
  // The simplest check: the element exists in the DOM and is not hidden by style.
  return true;
}

// ── Given ─────────────────────────────────────────────────────────────────────

Given('I open the todo app', function () {
  // The Before hook already calls this.loadApp() and populates this.document.
  // Nothing more to do.
});

Given('there are no todos', function () {
  // The app starts with no todos by default. Verify the list is empty.
  const list = this.document.querySelector('.todo-list');
  if (list) {
    const items = list.querySelectorAll('li');
    // If items exist, remove them (edge case if localStorage had data)
    for (const item of items) item.remove();
  }
});

Given('I have a todo {string}', function (title) {
  // Add a todo by simulating typing in the input and pressing Enter
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  const event = new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13 });
  input.dispatchEvent(event);
  // If the app uses keyup instead
  const eventUp = new this.window.KeyboardEvent('keyup', { key: 'Enter', keyCode: 13, which: 13 });
  input.dispatchEvent(eventUp);
});

Given('I have a completed todo {string}', function (title) {
  // First create the todo
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  const event = new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13 });
  input.dispatchEvent(event);
  const eventUp = new this.window.KeyboardEvent('keyup', { key: 'Enter', keyCode: 13, which: 13 });
  input.dispatchEvent(eventUp);
  // Then mark it as completed by clicking the toggle
  const items = this.document.querySelectorAll('.todo-list li');
  for (const item of items) {
    const label = item.querySelector('label');
    if (label && label.textContent.trim() === title) {
      const toggle = item.querySelector('.toggle');
      if (toggle) {
        toggle.checked = true;
        toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
      }
      break;
    }
  }
});

Given('I have todos {string} and {string}', function (title1, title2) {
  // First todo
  const input = this.document.querySelector('.new-todo');
  input.value = title1;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13 }));
  input.dispatchEvent(new this.window.KeyboardEvent('keyup', { key: 'Enter', keyCode: 13, which: 13 }));
  // Second todo
  input.value = title2;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13 }));
  input.dispatchEvent(new this.window.KeyboardEvent('keyup', { key: 'Enter', keyCode: 13, which: 13 }));
});

Given('all todos are marked completed', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const item of items) {
    const toggle = item.querySelector('.toggle');
    if (toggle && !toggle.checked) {
      toggle.checked = true;
      toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
    }
  }
});

Given('{string} is completed', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const item of items) {
    const label = item.querySelector('label');
    if (label && label.textContent.trim() === title) {
      const toggle = item.querySelector('.toggle');
      if (toggle) {
        toggle.checked = true;
        toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
      }
      break;
    }
  }
});

Given('localStorage has a todo {string}', function (title) {
  const data = [{ id: Date.now(), title: title, completed: false }];
  this.localStorage.setItem('todos-vanillajs', JSON.stringify(data));
});

Given('I am on the todo app', function () {
  // The Before hook already loaded the app. No extra action needed.
});

Given('the {string} filter is selected', function (filter) {
  // Navigate to the filter route
  const routeMap = { 'All': '#/', 'Active': '#/active', 'Completed': '#/completed' };
  const hash = routeMap[filter] || '#/';
  this.navigate(hash);
});

// ── When ──────────────────────────────────────────────────────────────────────

When('I type {string} in the new-todo input and press Enter', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13 }));
  input.dispatchEvent(new this.window.KeyboardEvent('keyup', { key: 'Enter', keyCode: 13, which: 13 }));
});

When('I click the toggle checkbox for {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const item of items) {
    const label = item.querySelector('label');
    if (label && label.textContent.trim() === title) {
      const toggle = item.querySelector('.toggle');
      if (toggle) {
        toggle.checked = !toggle.checked;
        toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
      }
      break;
    }
  }
});

When('I click the toggle-all checkbox', function () {
  const toggleAll = this.document.querySelector('.toggle-all');
  if (toggleAll) {
    toggleAll.checked = !toggleAll.checked;
    toggleAll.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  }
});

When('I click {string}', function (label) {
  if (label === 'Clear completed') {
    const btn = this.document.querySelector('.clear-completed');
    if (btn) btn.click();
  }
});

When('I mark {string} as completed', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const item of items) {
    const label = item.querySelector('label');
    if (label && label.textContent.trim() === title) {
      const toggle = item.querySelector('.toggle');
      if (toggle) {
        toggle.checked = true;
        toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
      }
      break;
    }
  }
});

When('I also mark {string} as completed', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const item of items) {
    const label = item.querySelector('label');
    if (label && label.textContent.trim() === title) {
      const toggle = item.querySelector('.toggle');
      if (toggle) {
        toggle.checked = true;
        toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
      }
      break;
    }
  }
});

When('I double-click the label for {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const item of items) {
    const label = item.querySelector('label');
    if (label && label.textContent.trim() === title) {
      label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
      break;
    }
  }
